To solve this problem using the Artificial Bee Colony (ABC) algorithm, we will follow these steps:

1. Initialize the colony with 50 random solutions (food sources) within the search space xϵ[-5, 5].
2. Evaluate the fitness of each solution.
3. Perform the employed bee phase, onlooker bee phase, and scout bee phase.
4. Repeat steps 2-3 for 100 iterations.
5. Find the best solution (maximum value of f(x)).

Since the ABC algorithm is a heuristic optimization algorithm, it is not possible to provide an exact solution using text only. However, I can provide you with a Python code implementation to solve the problem:

```python
import random
import numpy as np

def f(x):
    return x**3 - 8*x**2 + 2*x + 10

def fitness(x):
    return f(x)

def initialize_population(colony_size, lower_bound, upper_bound):
    return [random.uniform(lower_bound, upper_bound) for _ in range(colony_size)]

def employed_bee_phase(solutions, limit, lower_bound, upper_bound):
    for i, sol in enumerate(solutions):
        new_sol = sol + random.uniform(-1, 1) * (sol - random.choice(solutions))
        new_sol = max(min(new_sol, upper_bound), lower_bound)
        if fitness(new_sol) > fitness(sol):
            solutions[i] = new_sol
            limit[i] = 0
        else:
            limit[i] += 1
    return solutions, limit

def onlooker_bee_phase(solutions, limit, lower_bound, upper_bound):
    probabilities = [fitness(sol) / sum(fitness(sol) for sol in solutions) for sol in solutions]
    for i, sol in enumerate(solutions):
        if random.random() < probabilities[i]:
            new_sol = sol + random.uniform(-1, 1) * (sol - random.choice(solutions))
            new_sol = max(min(new_sol, upper_bound), lower_bound)
            if fitness(new_sol) > fitness(sol):
                solutions[i] = new_sol
                limit[i] = 0
            else:
                limit[i] += 1
    return solutions, limit

def scout_bee_phase(solutions, limit, max_limit, lower_bound, upper_bound):
    for i, sol in enumerate(solutions):
        if limit[i] >= max_limit:
            solutions[i] = random.uniform(lower_bound, upper_bound)
            limit[i] = 0
    return solutions, limit

def artificial_bee_colony(colony_size, max_iter, max_limit, lower_bound, upper_bound):
    solutions = initialize_population(colony_size, lower_bound, upper_bound)
    limit = [0] * colony_size

    for _ in range(max_iter):
        solutions, limit = employed_bee_phase(solutions, limit, lower_bound, upper_bound)
        solutions, limit = onlooker_bee_phase(solutions, limit, lower_bound, upper_bound)
        solutions, limit = scout_bee_phase(solutions, limit, max_limit, lower_bound, upper_bound)

    best_solution = max(solutions, key=fitness)
    return best_solution, f(best_solution)

colony_size = 50
max_iter = 100
max_limit = 20
lower_bound = -5
upper_bound = 5

best_solution, max_value = artificial_bee_colony(colony_size, max_iter, max_limit, lower_bound, upper_bound)
print("Best solution:", best_solution)
print("Max value of f(x):", max_value)
```

